# Reconstructed radial ψ4 from the (l,m,n,k) Hertz potential (Radpsi4fromHzpotmode,
# Sourceincoordinates.nb SC l.408/l.356, equality proven at SC IN176; Polcar & Witzany 2025,
# arXiv:2507.15720). Equatorial Schwarzschild (M=MB).

# ψ4 kernel: generated by the wolframscript reduction (oracle/psi4_from_hertz_oracle.wl),
# transcribed verbatim; no element-type pin.
using Perturbation: radial_jet
using NumericsCore: constjet, jadd, jscale, jmul, jinv

function _psi4_hertz_kernel(MB, rad, omega, mi, li, rhzb, drhzb)
    return ((-1)^mi*((-4*im)*drhzb*omega*(2*MB - rad)*rad*(6*MB^2 + 2*(-3 + li + li^2)*MB*rad + rad^2*(2 - li - li^2 + 2*omega^2*rad^2)) + (2*li^3*(-2*MB + rad)^2 + li^4*(-2*MB + rad)^2 + 2*li*(MB^2*(-4 - (4*im)*omega*rad) - rad^2*(1 + (4*im)*omega*rad + 4*omega^2*rad^2) + 2*MB*rad*(2 + (5*im)*omega*rad + 4*omega^2*rad^2)) + li^2*(MB^2*(-4 - (8*im)*omega*rad) + 4*MB*rad*(1 + (5*im)*omega*rad + 4*omega^2*rad^2) - rad^2*(1 + (8*im)*omega*rad + 8*omega^2*rad^2)) + 4*omega*((-12*im)*MB^3 + 6*MB^2*rad*(4*im + 3*omega*rad) + im*MB*rad^2*(-15 + (16*im)*omega*rad + 4*omega^2*rad^2) + 2*rad^3*(2*im + 2*omega*rad + im*omega^2*rad^2 + omega^3*rad^3)))*rhzb))/(32*rad^2)
end

"""
    psi4_from_hertz(l, m, n, k, a, p, e, x; Nmax=80) -> Function

Radial ψ4 reconstructed from the `(l,m,n,k)` Hertz potential on a Kerr geodesic `(a,p,e,x)` (M=1),
porting `Radpsi4fromHzpotmode`. Returns a callable of Boyer-Lindquist radius `r`.

The Hertz potential `RadHZ` (from [`hertz_potential_mode`](@ref)) enters as `rhzb = conj(RadHZ(r))`,
`drhzb = conj(RadHZ'(r))`, and the `_psi4_hertz_kernel` returns the reconstructed Weyl
scalar. By the CCK reconstruction identity (Shah & van de Meent 2015) the reconstruction for
`(l,-m,-n,-k)` equals the point-particle ψ4 amplitude divided by `r^4` in the vacuum region `r > p`
— the test grounding.
"""
function psi4_from_hertz(l::Integer, m::Integer, n::Integer, k::Integer,
        a::Real, p::Real, e::Real, x::Real; Nmax::Integer=80)
    RadHZ, dRadHZ, ω = hertz_potential_mode(l, m, n, k, a, p, e, x; Nmax=Nmax)
    return function (r::Real)
        rhzb = conj(RadHZ(r))
        drhzb = conj(dRadHZ(r))
        return _psi4_hertz_kernel(one(r), r, ω, m, l, rhzb, drhzb)
    end
end

# ── h44_from_hertz (Radh44fromHzpotmode, SC l.368/430/432) — reconstructed (4,4)=m̄m̄ metric ─────
# Weight bookkeeping: h_m̄m̄ is type {−2,+2} (sum 0); þ′² lowers the sum by 4 ⇒ Ψ carries SΨ=4;
# þ′ε′ has sum 0, ρ′ is type {−1,−1}. RadHZ† derivatives come exactly from the s=+2 radial ODE
# tower (radial_jet) — no finite differences in the þ′þ′ chain.

const _SΨ = 4    # GHP weight-sum of Ψ=Radf†[2,l,m] (h_m̄m̄ type {−2,2}, þ′² lowers sum by 4)

"Length-(N+1) jet of r^n at r0 (element type CT), reusing Operators jet products."
function _powjet(r0, n::Integer, N::Integer, ::Type{CT}) where {CT}
    rjet = zeros(CT, N+1); rjet[1] = CT(r0); N ≥ 1 && (rjet[2] = one(CT))
    n == 0 && return constjet(one(CT), N, CT)
    if n > 0
        p = constjet(one(CT), N, CT); for _ in 1:n; p = jmul(p, rjet); end; return p
    else
        p = constjet(one(CT), N, CT); for _ in 1:(-n); p = jmul(p, rjet); end; return jinv(p)
    end
end

"""
    h44_from_hertz(l, m, n, k, a, p, e, x; Nmax=80) -> Function

Finite-r reconstructed `(4,4)=m̄m̄` tetrad metric component from the `(l,m,n,k)` Hertz potential on a
Schwarzschild circular/spherical geodesic (M=1), porting `Radh44fromHzpotmode`. Returns a callable of
Boyer-Lindquist radius `r` giving the SWSH-free radial h44 mode.

Assembles `−(−1)^m·((3ε′+3ε′†+2ρ′)þ′Ψ + Ψ·B + þ′þ′Ψ)` with `Ψ=RadHZ†/r⁴`, `þ′` the native GHP
thorn-prime ([`thorn_prime`](@ref)), and `B` the spin-coefficient polynomial (SC l.368). The RadHZ†
Taylor tower comes from the s=+2 radial Teukolsky ODE (`radial_jet`), the amplitude from
[`hertz_potential_mode`](@ref). Grounded (necessary) by `h44 → 2·ψ4/ω²` at large r (Radh44asympt,
SC l.438) vs [`psi4_from_hertz`](@ref), and (sufficient) by r-independent proportionality to the
CCK vacuum m̄m̄ component (the IRG `H_mm` metric-reconstruction block whose reconstruction passes the
linearized-Einstein G⁽¹⁾=0 residual gate).
"""
function h44_from_hertz(l::Integer, m::Integer, n::Integer, k::Integer,
        a::Real, p::Real, e::Real, x::Real; Nmax::Integer=80, SΨ::Integer=_SΨ)
    RadHZ, dRadHZ, ω = hertz_potential_mode(l, m, n, k, a, p, e, x; Nmax=Nmax)
    sign44 = (-1)^m
    return function (r::Real)
        N = 4
        upjet = radial_jet(2, l, m, a, ω, r; bc=:Up, order=N)
        CT = eltype(upjet)
        hzamp = CT(RadHZ(r)) / upjet[1]                     # constant Hertz amplitude (up unit-transmission)
        Rdag = conj.(hzamp .* upjet)                        # RadHZ† Taylor tower
        Ψjet = jmul(Rdag, _powjet(r, 4, N, CT))         # Ψ = Radf†[2,l,m] = RadHZ†/ksim1⁴ = RadHZ†·r⁴
        # background spin coefficients + their þ′ (static, ω=0)
        sc = schw_spincoeff(r)
        εjet  = jscale(CT(-1), _powjet(r, -2, N, CT)) ; εjet = jscale(CT(1//2), εjet)  # ε′=−1/2r²  (M=1)
        ρpjet = jadd(jscale(CT(1//2), _powjet(r, -1, N, CT)),
                          jscale(CT(-1),  _powjet(r, -2, N, CT)))                          # ρ′=1/2r−1/r²
        bpε  = thorn_prime(εjet,  0,  0, r, 0.0)[1]          # þ′ε′  (ε′ charge-free)
        bpρp = thorn_prime(ρpjet, -1, -1, r, 0.0)[1]         # þ′ρ′  (ρ′ type {−1,−1})
        εp = CT(sc.ε′); εpd = CT(sc.ε′dag); ρp = CT(sc.ρ′)
        A = 3εp + 3εpd + 2ρp
        B = 2εp^2 + 4εp*εpd + 2εpd^2 + εp*ρp + εpd*ρp - 3ρp^2 + 2bpε + 2bpε + 3bpρp
        # þ′Ψ and þ′þ′Ψ (Ψ sum SΨ; þ′Ψ sum SΨ−2)
        bpΨjet = thorn_prime(Ψjet, SΨ, 0, r, ω)
        bpΨ   = bpΨjet[1]
        bp2Ψ  = thorn_prime(bpΨjet, SΨ-2, 0, r, ω)[1]
        Ψ0 = Ψjet[1]
        return -sign44 * (A*bpΨ + Ψ0*B + bp2Ψ)
    end
end

export psi4_from_hertz, h44_from_hertz
